parameters.text:
=You are a support team lead at UrbanThread (Indian online clothing store). Create a support ticket from this escalation. Phone numbers must be in E.164 format: if a 10-digit Indian number is given, add +91. Priority is high if the customer is angry, the refund is above Rs 5,000, the item is damaged or there is a payment problem.

Customer name: {{ $json.customer_name }}
Phone: {{ $json.phone }}
Order ID: {{ $json.order_id }}
Reason for escalation: {{ $json.reason }}
Conversation summary: {{ $json.conversation_summary }}

Answer with ONLY this JSON shape (fill every field): {"output": {"customer_name": "...", "phone": "...", "order_id": "...", "issue_type": "refund|return|delivery|damaged_item|payment|size|other", "sentiment": "positive|neutral|negative|angry", "priority": "low|medium|high", "summary": "...", "suggested_action": "..."}}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "customer_name": { "type": "string", "description": "Customer name, or 'Unknown' if not given" },
    "phone": { "type": "string", "description": "Customer phone in E.164 format (e.g. +919000000003), or empty string if not given" },
    "order_id": { "type": "string", "description": "Order ID like UT1003, or empty string if not relevant" },
    "issue_type": { "type": "string", "enum": ["refund", "return", "delivery", "damaged_item", "payment", "size", "other"] },
    "sentiment": { "type": "string", "enum": ["positive", "neutral", "negative", "angry"] },
    "priority": { "type": "string", "enum": ["low", "medium", "high"], "description": "high if angry, refund > Rs 5,000, damaged item or payment problem" },
    "summary": { "type": "string", "description": "2-3 sentence summary of the problem for the human agent" },
    "suggested_action": { "type": "string", "description": "One concrete next step for the human agent" }
  },
  "required": ["customer_name", "phone", "order_id", "issue_type", "sentiment", "priority", "summary", "suggested_action"]
}

parameters.jsCode:
// Take the AI ticket; fill anything missing from what the agent sent, and make every value
// fit the database (allowed words + column lengths), so saving the ticket can never fail.
const t = $json.output || {};
const inp = $('When Called by Agent').first().json;
const text = (String(inp.reason || '') + ' ' + String(inp.conversation_summary || '')).toLowerCase();
const pick = (v, allowed, dflt) => { v = String(v || '').toLowerCase().trim();
  return allowed.includes(v) ? v : (allowed.find(a => v.includes(a)) || dflt); };
let phone = String(t.phone || inp.phone || '').replace(/[^0-9+]/g, '');
if (/^[0-9]{10}$/.test(phone)) phone = '+91' + phone;  // Indian 10-digit number -> E.164
const oid = (String(t.order_id || '') + ' ' + String(inp.order_id || '') + ' ' + text).toUpperCase().match(/UT\d{4}/);
const issueGuess = text.includes('refund') ? 'refund' : text.includes('late') || text.includes('delay') ? 'delivery' : 'other';
const angry = /angry|manager|worst|third time|furious|complain/.test(text);
return [{ json: { output: {
  customer_name: String(t.customer_name || inp.customer_name || 'Unknown').slice(0, 100),
  phone: phone.slice(0, 20),
  order_id: oid ? oid[0] : '',
  issue_type: pick(t.issue_type, ['refund', 'return', 'delivery', 'damaged_item', 'payment', 'size', 'other'], issueGuess),
  sentiment: pick(t.sentiment, ['positive', 'neutral', 'negative', 'angry'], angry ? 'angry' : 'negative'),
  priority: pick(t.priority, ['low', 'medium', 'high'], 'high'),
  summary: String(t.summary || inp.conversation_summary || inp.reason || '').slice(0, 2000),
  suggested_action: String(t.suggested_action || 'Contact the customer and review the chat.').slice(0, 1000),
} } }];

